'use strict';
const names={cruza:['Cruza','Fixed wing · LTE / VPN'],quadpi:['quadpi','10-inch quad · RN03 wearable / mesh'],rn03:['RN03 aircraft','Separate Mini · awaiting connection']},colors={cruza:'#7ce1ba',quadpi:'#7dbcf4',rn03:'#d3a9ed'},cards={};
let watching=true,previous={},failures=0,busy=false;
for(const [id,[name,route]] of Object.entries(names)){
 const card=document.createElement('article');card.className='card';card.id=id;card.innerHTML='<div class="head"><div><h2></h2><small></small></div><span class="badge">WAITING</span></div>';card.querySelector('h2').textContent=name;card.querySelector('small').textContent=route;
 if(id==='rn03')card.innerHTML+='<div class="placeholder">Aircraft source not configured.<br>The RN03 wearable is a network relay. Its connection does not establish telemetry or video from RN03’s separate aircraft.</div>';
 else{card.innerHTML+='<div class="video"><iframe allow="autoplay; fullscreen; picture-in-picture"></iframe><div class="overlay" hidden>Video paused</div></div><div class="videofoot"><span>Waiting for video</span><button>Expand</button></div><details class="telemetry"><summary>Aircraft status</summary><div class="metrics"></div><div class="mission"></div><div class="details"></div></details>';card.querySelector('.telemetry').open=window.matchMedia('(min-width:1050px)').matches;const frame=card.querySelector('iframe');frame.title=name+' live video';frame.src=`http://127.0.0.1:8889/${id}?controls=false&muted=true`;card.querySelector('button').onclick=()=>card.requestFullscreen().catch(()=>{});}
 cards[id]=card;document.querySelector('#fleet').append(card);
}
function fmt(v,unit='',digits=1){return v===null||v===undefined?'—':typeof v==='number'?v.toFixed(digits)+unit:String(v)+unit;}
function metric(label,value){const n=document.createElement('div');n.className='metric';const s=document.createElement('small'),v=document.createElement('span');s.textContent=label;v.textContent=value;n.append(s,v);return n;}
function renderVehicle(v){const c=cards[v.name];if(!c)return;const badge=c.querySelector('.badge');badge.classList.toggle('live',v.online);badge.textContent=!v.configured?'UNCONFIGURED':v.online?'TELEMETRY LIVE':'TELEMETRY STALE';if(!v.configured)return;
 const box=c.querySelector('.metrics');box.replaceChildren();const fields=[['Mode',v.mode??'—'],['Arming',v.armed===null?'—':v.armed?'ARMED':'Disarmed'],['Battery',fmt(v.battery_voltage,' V')+' / '+fmt(v.battery_percent,'%',0)],['Relative altitude',fmt(v.position?.altitude_relative_m,' m')],['Ground speed',fmt(v.groundspeed_m_s,' m/s')],['GPS',v.gps?`Fix ${v.gps.fix_type} · ${fmt(v.gps.satellites,' sats',0)}`:'—'],['Roll / pitch',fmt(v.roll_deg,'°')+' / '+fmt(v.pitch_deg,'°')],['FC heartbeat',fmt(v.heartbeat_age,' s ago')]];fields.forEach(([k,val])=>box.append(metric(k,val)));
 const m=v.mission;c.querySelector('.mission').textContent=`Mission item: ${fmt(m.current_seq,'',0)} · Total: ${fmt(m.total,'',0)}\nState: ${m.state??'—'} · Last reached: ${fmt(m.last_reached_seq,'',0)}${m.last_reached_age!==null?' ('+fmt(m.last_reached_age,' s ago',0)+')':''}`;c.querySelector('.details').textContent=v.error||(v.position?`${v.position.latitude.toFixed(6)}, ${v.position.longitude.toFixed(6)} · ${fmt(v.position_age,' s old')}`:v.online?'Waiting for a valid, current GPS position.':'Waiting for a fresh flight-controller heartbeat.');
}
function drawMap(fleet){ window.fleetMap.update(fleet); }
function offline(){document.querySelector('#connection').textContent='Dashboard disconnected — telemetry unavailable';for(const id of ['cruza','quadpi']){cards[id].querySelector('.badge').textContent='DASHBOARD OFFLINE';cards[id].querySelector('.badge').classList.remove('live');cards[id].querySelector('.metrics').replaceChildren(metric('Status','Unavailable'));cards[id].querySelector('.mission').textContent='Mission status unavailable';cards[id].querySelector('.details').textContent='';}drawMap([]);}
async function tick(){if(busy)return;busy=true;try{const res=await fetch('/status?watch='+(watching?'1':'0'),{signal:AbortSignal.timeout(5000)});if(!res.ok)throw Error('Dashboard unavailable');const status=await res.json(),now=performance.now();status.fleet.forEach(renderVehicle);drawMap(status.fleet);for(const f of status.feeds){const prev=previous[f.name],rate=prev?Math.round(Math.max(0,f.bytes-prev.bytes)*8/(now-prev.time)):0;cards[f.name].querySelector('.videofoot span').textContent=!watching?'Video paused':f.receiving?`Video receiving · ${rate} kb/s`:'Waiting for video';previous[f.name]={bytes:f.bytes,time:now};}document.querySelector('#connection').textContent=`Updated ${new Date().toLocaleTimeString()} · Cruza extra video ${(status.feeds.find(f=>f.name==='cruza').bytes/1e6).toFixed(1)} MB this session`;failures=0;}catch(e){if(++failures>=2)offline();}finally{busy=false;}}
 document.querySelector('#toggle').onclick=()=>{watching=!watching;document.querySelector('#toggle').textContent=watching?'Pause video':'Resume video';for(const id of ['cruza','quadpi']){cards[id].querySelector('.overlay').hidden=watching;cards[id].querySelector('iframe').src=watching?`http://127.0.0.1:8889/${id}?controls=false&muted=true`:'about:blank';}if(!watching)fetch('/pause',{method:'POST'}).catch(()=>{});tick();};tick();setInterval(tick,1500);
